UPDATE public.recipes r SET nutrition=x.nutrition,notes=x.notes FROM jsonb_to_recordset($data$[{"language": "es", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 de 8 porciones de aperitivo, aproximadamente 94 g", "note": "Estimación por ración; los productos y el rendimiento pueden cambiar los valores.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Consejos y conservación</h3><p>La mozzarella debe ser de baja humedad; la fresca necesita escurrirse muy bien y cambia la textura. Para una versión sin carne, sustituye el salami por garbanzos cocidos escurridos; cambia el sabor y la nutrición. Conserva tapado a 4 °C o menos y consume preferiblemente en 24 horas por textura. No dejes los perecederos fuera del frío más de 2 horas, o 1 hora si el ambiente supera 32 °C. Contiene leche; revisa los alérgenos del salami y del acompañamiento.</p><h3>Fuentes</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "en", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 of 8 appetizer servings, about 94 g", "note": "Estimated per serving; products and yield can change these values.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Tips and storage</h3><p>Use low-moisture mozzarella; fresh mozzarella needs thorough draining and changes the texture. For a meat-free variation, replace salami with drained cooked chickpeas; flavor and nutrition change. Keep covered at 4 °C / 40 °F or below and preferably eat within 24 hours for texture. Limit time out of refrigeration to 2 hours, or 1 hour above 32 °C / 90 °F. Contains milk; check salami and accompaniment allergen labels.</p><h3>Sources</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "de", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 von 8 Vorspeisenportionen, etwa 94 g", "note": "Schätzwerte pro Portion; Produkte und Ausbeute können die Werte verändern.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Tipps und Aufbewahrung</h3><p>Schnittfesten Mozzarella verwenden; frischer Mozzarella muss gut abtropfen und verändert die Konsistenz. Salami lässt sich für eine fleischfreie Variante durch abgetropfte gekochte Kichererbsen ersetzen; Geschmack und Nährwerte ändern sich. Abgedeckt bei höchstens 4 °C lagern und für gute Konsistenz möglichst innerhalb von 24 Stunden essen. Höchstens 2 Stunden ungekühlt stehen lassen, bei über 32 °C nur 1 Stunde. Enthält Milch; Allergene von Salami und Beilagen prüfen.</p><h3>Quellen</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "fr", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 des 8 portions apéritives, environ 94 g", "note": "Estimation par portion ; les produits et le rendement peuvent modifier ces valeurs.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Conseils et conservation</h3><p>Choisissez une mozzarella à faible humidité ; la mozzarella fraîche doit être bien égouttée et modifie la texture. Pour une variante sans viande, remplacez le salami par des pois chiches cuits égouttés ; goût et nutrition changent. Gardez couvert à 4 °C maximum et consommez de préférence sous 24 heures pour la texture. Ne laissez pas hors du froid plus de 2 heures, ou 1 heure au-dessus de 32 °C. Contient du lait ; vérifiez les allergènes du salami et des accompagnements.</p><h3>Sources</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "it", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 di 8 porzioni da aperitivo, circa 94 g", "note": "Stima per porzione; prodotti e resa possono modificare questi valori.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Consigli e conservazione</h3><p>Usa mozzarella a bassa umidità; quella fresca va scolata bene e modifica la consistenza. Per una variante senza carne, sostituisci il salame con ceci cotti scolati; cambiano gusto e valori nutrizionali. Conserva coperto a non più di 4 °C e consuma preferibilmente entro 24 ore per la consistenza. Non lasciare fuori frigo oltre 2 ore, o 1 ora sopra 32 °C. Contiene latte; controlla gli allergeni di salame e accompagnamenti.</p><h3>Fonti</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "ja", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "前菜8人分のうち1人分、約94 g", "note": "1人分の推定値です。使用する製品や出来上がり量によって変わります。", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>コツと保存方法</h3><p>低水分のモッツァレラを使います。フレッシュタイプは十分な水切りが必要で、食感も変わります。肉を使わない場合はサラミを水切りしたゆでひよこ豆に替えられますが、味と栄養値は変わります。ふたをして4 °C以下で保存し、食感のためできれば24時間以内に食べます。常温に置く時間は2時間以内、32 °Cを超える場合は1時間以内にします。乳を含みます。サラミや添え物のアレルゲン表示も確認してください。</p><h3>参考資料</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}, {"language": "pt", "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 de 8 porções de aperitivo, cerca de 94 g", "note": "Estimativa por porção; os produtos e o rendimento podem alterar os valores.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "notes": "<h3>Dicas e conservação</h3><p>Use muçarela de baixa umidade; a fresca precisa escorrer bem e muda a textura. Para uma versão sem carne, troque o salame por grão-de-bico cozido escorrido; sabor e nutrição mudam. Guarde tampado a 4 °C ou menos e consuma de preferência em 24 horas para preservar a textura. Não deixe fora da geladeira por mais de 2 horas, ou 1 hora acima de 32 °C. Contém leite; confira os alérgenos do salame e dos acompanhamentos.</p><h3>Fontes</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>"}]$data$::jsonb) AS x(language text,nutrition jsonb,notes text) WHERE r.recipe_group_id='056722fb-4404-4610-aa3a-a5e9dace5b82' AND r.language=x.language;